export type GuideCategory = 'Grammar' | 'Loanwords' | 'Phrases' | 'Conjugations';

export interface SectionImage {
	/** Path under public/, e.g. '/images/ser-vs-estar-diagram.svg'. */
	src: string;
	/** Describes what the image shows. */
	alt: string;
	/** Attribution + license, supports markdown links. Omit only for self-made diagrams. */
	credit?: string;
}

export interface GuideSection {
	heading: string;
	body: string[];
	/** Optional in-body image, rendered after this section's paragraphs. */
	image?: SectionImage;
}

export interface FaqItem {
	question: string;
	answer: string;
}

export interface Source {
	label: string;
	url: string;
}

/**
 * Surfaced as a callout near the top of the page. Exists mainly for slang/loanword
 * entries where register and regional variation ARE the answer, not a footnote —
 * see CLAUDE.md section 6 ("俚语与文化敏感内容的处理"). Optional everywhere else.
 */
export interface UsageNote {
	register?: 'neutral' | 'casual' | 'informal' | 'formal' | 'vulgar' | 'offensive';
	/** e.g. "Playful/affectionate in Mexico; can read as an insult in Spain." */
	regionNote?: string;
}

export interface ConjugationForm {
	/** e.g. "yo", "tú", "je", "ich" */
	pronoun: string;
	form: string;
}

export interface ConjugationTense {
	/** e.g. "Present", "Preterite", "Imperfect", "Future", "Conditional", "Subjunctive (present)" */
	tense: string;
	forms: ConjugationForm[];
}

/**
 * Generated by `tools/conjugate.mjs` — regular verbs via the ending-rule functions,
 * irregular verbs from the hand-verified IRREGULAR_VERBS table in that file. See the
 * module docstring there for why this must never be typed in from memory.
 */
export interface ConjugationTable {
	/** Infinitive, e.g. "ser". */
	verb: string;
	language: string;
	translation: string;
	regularity: 'regular' | 'irregular' | 'stem-changing';
	tenses: ConjugationTense[];
	/** The authoritative grammar source the table was checked against. */
	source: Source & { note?: string };
}

export interface Guide {
	slug: string;
	category: GuideCategory;
	title: string;
	description: string;
	/** Original publication date. Falls back to `updated` when unset, so only articles that have since been edited need it. */
	published?: string;
	updated: string;
	/** One or two sentences summarizing the core finding/argument, surfaced above the fold for GEO/AI-search extraction. */
	coreSummary: string;
	/** Primary target/source language this entry is about, e.g. "Spanish". Omit for entries that aren't language-specific (rare). */
	language?: string;
	usageNote?: UsageNote;
	conjugation?: ConjugationTable;
	sections: GuideSection[];
	faq?: FaqItem[];
	sources?: Source[];
	/** Path under public/, e.g. '/images/slug.jpg'. Falls back to /favicon.svg when unset. */
	image?: string;
	/** Describes what the photo shows. Falls back to the article title when unset. */
	imageAlt?: string;
	/** Attribution text, supports markdown links like body/FAQ text. */
	imageCredit?: string;
}

